/** Which band does a grade-level string belong to? */
function resolveSf9Band(gradeLevel) {
  const g = String(gradeLevel || '').toLowerCase();
  if (/grade 1\b|grade 2\b|grade 3\b/.test(g)) return 'Grades 1-3';
  if (/grade 4\b|grade 5\b|grade 6\b/.test(g)) return 'Grades 4-6';
  if (/grade 7\b|grade 8\b|grade 9\b|grade 10\b/.test(g)) return 'Grades 7-10';
  if (/grade 11\b|grade 12\b/.test(g)) return 'SHS';
  return 'Grades 7-10';   // safest default
}

